use renderer::graph::{
    Access, AccessKind, AccessPurpose, AccessRange, BufferDesc, GraphCapacity, GraphPool,
    PassKind, ComputeTransform,
};
use renderer::engine::{Draw, Engine, EngineCapacity, IDENTITY, Material, MeshData, SnapshotPool, Vertex, View};
use std::{hint::black_box, time::Instant};

const WARMUP: usize = 8;

#[cfg(windows)]
fn pin_measurement_process() {
    use std::ffi::c_void;
    unsafe extern "system" {
        fn GetCurrentProcess() -> *mut c_void;
        fn GetProcessAffinityMask(process: *mut c_void, process_mask: *mut usize, system_mask: *mut usize) -> i32;
        fn SetProcessAffinityMask(process: *mut c_void, mask: usize) -> i32;
    }
    let mut allowed = 0usize;
    let mut system = 0usize;
    // Only this probe process is pinned, identically for before and after.
    unsafe {
        let process = GetCurrentProcess();
        assert_ne!(GetProcessAffinityMask(process, &mut allowed, &mut system), 0);
        assert_ne!(allowed, 0);
        let selected = allowed & allowed.wrapping_neg();
        assert_ne!(SetProcessAffinityMask(process, selected), 0);
        eprintln!("measurement_process_affinity_mask={selected:#x}");
    }
}

fn capacity(n: usize) -> GraphCapacity {
    GraphCapacity {
        resources: 1,
        passes: n,
        accesses: n,
        draws: 0,
        dependencies: n,
        initial_ranges: 0,
        name_bytes: n + 1,
        upload_bytes: 0,
        edges: n,
        segments: 2 * n + 1,
        readers: n,
    }
}

fn report(scenario: &str, n: usize, raw: &[u128]) {
    let mut sorted = raw.to_vec();
    sorted.sort_unstable();
    println!(
        r#"{{"scenario":"{scenario}","passes":{n},"median_ns":{},"raw_ns":{raw:?}}}"#,
        sorted[sorted.len() / 2]
    );
}

fn intervals(n: usize, order: &str, wide_read: bool) {
    let mut offsets: Vec<_> = (0..n).collect();
    if order == "descending" {
        offsets.reverse();
    } else if order == "shuffled" {
        let mut seed = 0x6a09_e667_f3bc_c909_u64;
        for index in (1..n).rev() {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            offsets.swap(index, (seed % (index as u64 + 1)) as usize);
        }
    }
    let mut pool = GraphPool::new(capacity(n + 1), 1).unwrap();
    let mut raw = Vec::with_capacity(9);
    for sample in 0..WARMUP + 9 {
        let mut graph = pool.begin().unwrap();
        let stride = if wide_read { 4 } else { 8 };
        let buffer = graph.buffer("b", BufferDesc { size: n as u64 * stride }).unwrap();
        for &offset in &offsets {
            let start = offset as u64 * stride;
            graph.declare_pass("p", PassKind::Copy, &[Access {
                resource: buffer.into(),
                range: AccessRange::Buffer(start..start + 4),
                kind: AccessKind::Write,
                purpose: AccessPurpose::CopyDestination,
            }], true).unwrap();
        }
        if wide_read {
            graph.declare_pass("r", PassKind::Copy, &[Access {
                resource: buffer.into(),
                range: AccessRange::Buffer(0..n as u64 * stride),
                kind: AccessKind::Read,
                purpose: AccessPurpose::CopySource,
            }], true).unwrap();
        }
        let started = Instant::now();
        let plan = graph.compile().unwrap();
        let elapsed = started.elapsed().as_nanos();
        assert_eq!(plan.pass_count(), n + usize::from(wide_read));
        black_box(&plan);
        if sample >= WARMUP { raw.push(elapsed); }
    }
    let scenario = if wide_read { "fragmented_wide_read_compile" } else { "fragmented_compile" };
    report(&format!("{scenario}_{order}"), n, &raw);
}

fn dependencies(n: usize) {
    let mut pool = GraphPool::new(capacity(n), 1).unwrap();
    let mut handles = Vec::with_capacity(n);
    let mut raw = Vec::with_capacity(9);
    for sample in 0..WARMUP + 9 {
        let mut graph = pool.begin().unwrap();
        handles.clear();
        for _ in 0..n {
            handles.push(graph.declare_pass("p", PassKind::Copy, &[], true).unwrap());
        }
        let started = Instant::now();
        for p in 1..n {
            graph.depends_on(handles[p], handles[p - 1]).unwrap();
        }
        let elapsed = started.elapsed().as_nanos();
        black_box(&graph);
        if sample >= WARMUP { raw.push(elapsed); }
    }
    report("explicit_dependency_insertion", n, &raw);
}

fn fallback_compile(n: usize, culled_writes: bool) {
    let mut pool = GraphPool::new(capacity(n + 1), 1).unwrap();
    let mut handles = Vec::with_capacity(n);
    let mut raw = Vec::with_capacity(9);
    for sample in 0..WARMUP + 9 {
        let mut graph = pool.begin().unwrap();
        let buffer = graph.buffer("b", BufferDesc { size: n as u64 * 4 }).unwrap();
        handles.clear();
        for offset in 0..n {
            let start = offset as u64 * 4;
            handles.push(graph.declare_pass("p", PassKind::Copy, &[Access {
                resource: buffer.into(), range: AccessRange::Buffer(start..start + 4),
                kind: AccessKind::Write, purpose: AccessPurpose::CopyDestination,
            }], !culled_writes).unwrap());
        }
        if culled_writes {
            graph.declare_pass("w", PassKind::Copy, &[Access {
                resource: buffer.into(), range: AccessRange::Buffer(0..n as u64 * 4),
                kind: AccessKind::Write, purpose: AccessPurpose::CopyDestination,
            }], true).unwrap();
        } else {
            for i in 0..n - 1 { graph.depends_on(handles[i], handles[i + 1]).unwrap(); }
        }
        graph.export_buffer(buffer).unwrap();
        let started = Instant::now();
        let plan = graph.compile().unwrap();
        let elapsed = started.elapsed().as_nanos();
        assert_eq!(plan.pass_count(), if culled_writes { 1 } else { n });
        black_box(&plan);
        if sample >= WARMUP { raw.push(elapsed); }
    }
    report(if culled_writes { "culled_overwritten_writers" } else { "backward_disjoint_chain_compile" }, n, &raw);
}

fn engine_graph(meshes: usize, draws: usize, dead_branch: bool) {
    let mut engine = Engine::new(EngineCapacity { meshes, materials: 1, retired_mesh_versions: 0 }).unwrap();
    let material = engine.create_material(Material::default()).unwrap();
    let mesh_handles: Vec<_> = (0..meshes).map(|_| engine.create_mesh(MeshData::new(
        &[[-0.5, -0.5, 0.5], [0.5, -0.5, 0.5], [0.0, 0.5, 0.5]].map(|position| Vertex { position, color: [1.0; 4] }),
        &[0, 1, 2],
    ).unwrap()).unwrap()).collect();
    let draw_input: Vec<_> = (0..draws).map(|i| Draw { mesh: mesh_handles[i % meshes], material, world_from_model: IDENTITY }).collect();
    let snapshots = SnapshotPool::new(draws, 1).unwrap();
    let view = View { width: 32, height: 24, clip_from_world: IDENTITY, clear_color: [0.0, 0.0, 0.0, 1.0] };
    let captured = engine.snapshot(&snapshots, &view, &draw_input).unwrap();
    let mut pool = GraphPool::new(GraphCapacity {
        resources: 2 * meshes + 10, passes: 2 * meshes + 16, accesses: 4 * meshes + 64,
        draws, dependencies: 0, initial_ranges: 0, name_bytes: 100 * meshes + 4096, upload_bytes: 0,
        edges: 8 * meshes + 64, segments: 4 * meshes + 64, readers: 8 * meshes + 64,
    }, 1).unwrap();
    let mut raw = Vec::with_capacity(9);
    let mut pass_count = 0;
    for sample in 0..WARMUP + 9 {
        let frame = captured.build_graph(&mut pool, true, |g, color| {
            let desc = g.image_desc(color)?;
            let a = g.image("a", desc)?;
            let b = g.image("b", desc)?;
            g.compute("compute.a", color, a, ComputeTransform::Invert)?;
            g.compute("compute.b", a, b, ComputeTransform::SwapRedBlue)?;
            if dead_branch {
                let dead = g.image("dead", desc)?;
                g.compute("dead.compute", color, dead, ComputeTransform::Invert)?;
            }
            Ok(b)
        }).unwrap();
        let started = Instant::now();
        let plan = frame.graph.compile().unwrap();
        let elapsed = started.elapsed().as_nanos();
        pass_count = plan.pass_count();
        assert_eq!(pass_count, 2 * meshes + 4);
        black_box(&plan);
        if sample >= WARMUP { raw.push(elapsed); }
    }
    report(&format!("engine_meshes{meshes}_draws{draws}_dead{dead_branch}"), pass_count, &raw);
}

fn main() {
    #[cfg(windows)]
    pin_measurement_process();
    // Stabilize the pinned process before the first microsecond-scale cases.
    // This is outside every build/compile sample and identical for all variants.
    let warmup = Instant::now();
    let mut warm_state = 1u64;
    while warmup.elapsed() < std::time::Duration::from_millis(100) {
        warm_state = black_box(warm_state.wrapping_mul(6364136223846793005).wrapping_add(1));
    }
    for n in [16, 128, 1024, 2048, 4096, 8192] {
        for order in ["ascending", "descending", "shuffled"] { intervals(n, order, false); }
        for order in ["ascending", "shuffled"] { intervals(n, order, true); }
    }
    for n in [1024, 2048, 4096, 8192, 16384] { dependencies(n); }
    for n in [128, 1024, 8192] {
        fallback_compile(n, false);
        fallback_compile(n, true);
    }
    for (meshes, draws) in [(1, 8192), (128, 1024), (1024, 1024)] {
        engine_graph(meshes, draws, false);
        engine_graph(meshes, draws, true);
    }
}

timing_helpers.source_utf8:
"""Plan, capture, export and analyze non-admin, owned Bistro Tracy runs.

Use matched portable Tracy 0.14.1 binaries. READY follows warmup; the private
capture connects to localhost, then GO permits the target to verify connection
and begin its ROI. DONE precedes capture SIGINT/flush; END releases post-ROI
readback and shutdown. Disconnected mode measures the same instrumented bytes
without a collector. No command changes UAC, ETW, kernel or machine settings.
"""
import argparse
from datetime import datetime, timezone
import json
import os
from pathlib import Path
import queue
import re
import socket
import subprocess
import sys
import threading
import time
import uuid

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "tools/cpu_profile"))
sys.path.insert(0, str(ROOT / "tools/bistro"))
from identity import sha256, verify_manifest
from measure_runtime import validate_report
from windows import hidden_console, owned_listener, require_nonadmin
from zone_analysis import analyze_zones

TRACY_VERSION = "0.14.1"
TRACY_FEATURES = {"enable", "ondemand", "only-localhost"}
DIAGNOSTICS = {"development-validation", "vulkan-diagnostics", "d3d12-diagnostics", "graph-diagnostics", "memory-profiling"}


def utc():
    return datetime.now(timezone.utc).isoformat()


def write_json(path, value):
    Path(path).write_text(json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False) + "\n", encoding="utf-8")


def load(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def file_identity(path):
    path = Path(path).resolve()
    return {"path": str(path), "sha256": sha256(path), "size_bytes": path.stat().st_size}


def verify_file(record):
    if file_identity(record["path"]) != record:
        raise ValueError("Archived input/tool identity changed: " + record["path"])


def check_tool_provenance(path, tools):
    provenance = load(path)
    if provenance.get("tracy_version") != TRACY_VERSION or provenance.get("token_elevation") != 0:
        raise ValueError("Tool provenance must identify matched non-admin Tracy " + TRACY_VERSION)
    for role in ("capture", "csvexport"):
        recorded = provenance.get("tools", {}).get("tracy-" + role, {})
        if (recorded.get("sha256") != tools[role]["sha256"]
                or Path(recorded.get("path", "")).resolve() != Path(tools[role]["path"])):
            raise ValueError("Tool executable differs from archived bundle provenance")
    archive = provenance.get("archive", {})
    if not archive.get("path") or sha256(archive["path"]) != archive.get("sha256"):
        raise ValueError("Portable archive bytes differ from bundle provenance")
    return file_identity(archive["path"])


def check_instrumented(manifest):
    build = manifest["build"]
    features = set(build.get("effective_features", []))
    if (build.get("instrumentation") != "tracy" or build.get("artifact_class") != "tracy-instrumented"
            or "tracy" not in features or build.get("example") != "bistro"):
        raise ValueError("Tracy requires an explicitly archived instrumented Bistro build")
    if build.get("profile") not in ("release", "profiling") or features & DIAGNOSTICS:
        raise ValueError("Tracy requires release-derived optimization without validation diagnostics")
    if not {"vulkan", "d3d12"}.issubset(features):
        raise ValueError("Use one instrumented artifact containing both APIs")
    dependencies = build.get("instrumentation_dependencies", [])
    if {item["target"] for item in dependencies} != {"tracy_client", "tracy_client_sys"}:
        raise ValueError("Missing actual Tracy dependency feature proof")
    for item in dependencies:
        if set(item.get("features", [])) != TRACY_FEATURES:
            raise ValueError("Tracy dependency enables unsupported collection features")
        version = "0.19.0" if item["target"] == "tracy_client" else "0.30.1"
        if not item.get("package_id", "").endswith("@" + version):
            raise ValueError("Tracy dependency version differs from the matched 0.14.1 tool contract")
    source = manifest.get("git", {})
    if (source.get("dirty_status") != "" or not re.fullmatch(r"[a-f0-9]{40}", source.get("commit", ""))
            or not source.get("source_hashes")):
        raise ValueError("Tracy measurements require committed, identified build sources")


def make_plan(args):
    for name in ("frames", "warmup", "width", "height", "inflight"):
        value = getattr(args, name)
        if type(value) is not int or value <= 0:
            raise ValueError(name + " must be a positive integer")
    if not 0 < args.timeout_seconds <= 3600 or not 0 < args.flush_timeout_seconds <= 120:
        raise ValueError("Timeout must be (0,3600]; flush timeout (0,120]")
    if not 16 <= args.max_output_mib <= 65536:
        raise ValueError("max-output-mib must be [16,65536]")
    manifest_path = Path(args.build_manifest).resolve()
    manifest = verify_manifest(manifest_path)
    check_instrumented(manifest)
    output = Path(args.output).resolve()
    if output.exists():
        raise ValueError("Output must be a new directory; existing artifacts are never overwritten")
    binary = (manifest_path.parent / manifest["binary"]["path"]).resolve()
    command = [str(binary), "--api", args.api, "--view", args.view, "--width", str(args.width),
               "--height", str(args.height), "--frames", str(args.frames), "--warmup", str(args.warmup),
               "--inflight", str(args.inflight), "--output", str(output / "target")]
    inputs = {"conditions": file_identity(ROOT / "tools/bistro/conditions.json")}
    if args.fixture:
        command += ["--fixture"]
    else:
        inputs["cook_manifest"] = file_identity(args.manifest)
        command += ["--manifest", inputs["cook_manifest"]["path"]]
    tools = {}
    if args.mode == "connected":
        if not args.capture_exe or not args.csvexport_exe:
            raise ValueError("Connected capture requires explicit matched capture and csvexport executables")
        tools = {"capture": file_identity(args.capture_exe), "csvexport": file_identity(args.csvexport_exe)}
        command += ["--capture-handshake"]
    if args.tool_provenance:
        inputs["tool_provenance"] = file_identity(args.tool_provenance)
        if tools:
            inputs["tool_archive"] = check_tool_provenance(args.tool_provenance, tools)
    return {"schema_version": 1, "created_utc": utc(), "mode": args.mode, "api": args.api,
            "output": str(output), "cwd": str(Path(args.cwd).resolve()),
            "build_manifest": file_identity(manifest_path), "binary": manifest["binary"], "pdb": manifest["pdb"],
            "source": manifest["git"], "build": manifest["build"], "inputs": inputs, "tools": tools,
            "tracy_version": TRACY_VERSION, "command": command, "frames": args.frames,
            "warmup": args.warmup, "width": args.width, "height": args.height, "inflight": args.inflight,
            "fixture": args.fixture, "view": "fixture" if args.fixture else args.view,
            "timeout_seconds": args.timeout_seconds, "flush_timeout_seconds": args.flush_timeout_seconds,
            "max_output_bytes": args.max_output_mib * 1024 * 1024,
            "quota_scope": "Polling guard over owned output files; collector in-memory buffers and a single native write may transiently exceed the file quota. No preexisting outputs are reused.",
            "capture_command": ([tools["capture"]["path"], "-a", "127.0.0.1", "-p", "8086", "-o", str(output / "capture.tracy")] if tools else None),
            "target_environment": {"TRACY_PORT": "8086", "RENDERER_TRACY_CAPTURE_ID": uuid.uuid4().hex},
            "contract": "Instrumented elapsed wall zones only; not normal-release results, CPU samples or scheduler attribution. Serial owned process, localhost only, hidden private capture console, verified non-elevated tokens, no system settings changes."}


def verify_plan(plan):
    verify_file(plan["build_manifest"])
    manifest = verify_manifest(plan["build_manifest"]["path"])
    check_instrumented(manifest)
    if manifest["binary"] != plan["binary"] or manifest["pdb"] != plan["pdb"]:
        raise ValueError("Build identity differs from plan")
    for record in [*plan["inputs"].values(), *plan["tools"].values()]:
        verify_file(record)


def drain(process, path, events, prefixes):
    try:
        with Path(path).open("w", encoding="utf-8", newline="") as log:
            while line := process.stdout.readline(1024 * 1024 + 1):
                if len(line) > 1024 * 1024:
                    raise ValueError("Protocol/log line exceeds 1 MiB")
                log.write(line)
                log.flush()
                for prefix in prefixes:
                    if line.startswith(prefix + " "):
                        events.put_nowait((prefix, json.loads(line[len(prefix) + 1:])))
    except Exception as error:
        events.put_nowait(("ERROR", str(error)))
    finally:
        process.stdout.close()


def wait_event(process, events, expected, guard):
    while True:
        guard()
        try:
            kind, payload = events.get(timeout=0.05)
        except queue.Empty:
            if process.poll() is not None:
                # Drain can deliver a final line immediately after process exit.
                try:
                    kind, payload = events.get(timeout=0.2)
                except queue.Empty as error:
                    raise RuntimeError("Process exited before " + expected) from error
            else:
                continue
        if kind != expected or not isinstance(payload, dict) or payload.get("pid") != process.pid:
            raise ValueError(f"Expected owned {expected}, received {kind}: {payload}")
        return payload


def send(process, value):
    process.stdin.write(value + "\n")
    process.stdin.flush()


def stop_owned(process):
    if process is not None and process.poll() is None:
        process.kill()
        process.wait(timeout=10)


def checked_handshake(payload, plan, *, ready):
    if payload.get("api") != plan["api"] or payload.get("measured_frames") != plan["frames"]:
        raise ValueError("Handshake workload/ROI differs from plan")
    if payload.get("tracy_connected") is not (not ready):
        raise ValueError("Unexpected Tracy connection at handshake boundary")
    if payload.get("capture_id") != plan["target_environment"]["RENDERER_TRACY_CAPTURE_ID"]:
        raise ValueError("Handshake does not identify the exact planned run")
    if ready:
        if payload.get("warmup_done") is not True or payload.get("warmup_frames") != plan["warmup"]:
            raise ValueError("Target did not establish requested warmup")
        if payload.get("conditions_sha256") != plan["inputs"]["conditions"]["sha256"]:
            raise ValueError("Target embedded conditions differ from the planned source")
        if not plan["fixture"] and payload.get("cook_manifest_sha256") != plan["inputs"]["cook_manifest"]["sha256"]:
            raise ValueError("Target cook input differs from plan")


def require_available_local_port():
    # A known occupied port is refused before the target/collector is launched.
    # The target's own disconnected->connected handshake also prevents accepting
    # a trace if a different process wins the port after this observation.
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as probe:
        if sys.platform == "win32":
            probe.setsockopt(socket.SOL_SOCKET, socket.SO_EXCLUSIVEADDRUSE, 1)
        probe.bind(("127.0.0.1", 8086))


def capture(plan):
    if sys.platform != "win32":
        raise ValueError("Capture requires Windows; analysis and planning are portable")
    verify_plan(plan)
    output = Path(plan["output"])
    output.mkdir(parents=True, exist_ok=False)
    write_json(output / "plan.json", plan)
    result = {"schema_version": 1, "status": "running", "capture_completed": False,
              "trace_content_verified": False, "plan": plan,
              "started_utc": utc(), "tokens": {}, "events": {}}
    write_json(output / "capture.json", result)
    target = broker = None
    readers = []
    started = time.monotonic()
    deadline = started + plan["timeout_seconds"]

    def guard():
        if time.monotonic() > deadline:
            raise TimeoutError("Owned Tracy run exceeded its bounded timeout")
        size = sum(path.stat().st_size for path in output.rglob("*") if path.is_file())
        if size > plan["max_output_bytes"]:
            raise ValueError("Owned Tracy output exceeded its bounded quota")

    def watch(process, name, prefixes):
        events = queue.Queue(maxsize=16)
        reader = threading.Thread(target=drain, args=(process, output / (name + ".stdout.txt"), events, prefixes), daemon=True)
        readers.append(reader)
        reader.start()
        return events

    try:
        result["tokens"]["controller"] = require_nonadmin()
        if plan["mode"] == "connected":
            result["capture_help"] = run_logged([plan["tools"]["capture"]["path"]], output, "capture-help", 15, (1,))
            help_text = (output / "capture-help.stdout.txt").read_text(encoding="utf-8", errors="replace")
            if "tracy-capture " + TRACY_VERSION not in help_text:
                raise ValueError("Capture help does not identify matched Tracy " + TRACY_VERSION)
        require_available_local_port()
        # Start no instrumented target before proving caller is non-elevated.
        with (output / "target.stderr.txt").open("wb") as stderr:
            target = subprocess.Popen(plan["command"], cwd=plan["cwd"], stdin=subprocess.PIPE,
                                      stdout=subprocess.PIPE, stderr=stderr, text=True, encoding="utf-8", errors="replace",
                                      env=dict(os.environ, **plan["target_environment"]),
                                      creationflags=subprocess.CREATE_NO_WINDOW)
            result["tokens"]["target"] = require_nonadmin(target.pid, handle=target._handle)
            target_events = watch(target, "target", ("BISTRO_READY", "BISTRO_DONE"))
            if plan["mode"] == "connected":
                ready = wait_event(target, target_events, "BISTRO_READY", guard)
                checked_handshake(ready, plan, ready=True)
                result["events"]["ready"] = ready
                result["listener"] = owned_listener(target.pid)
                specification = {"command": plan["capture_command"], "cwd": plan["cwd"],
                                 "stdout": str(output / "collector.stdout.txt"), "stderr": str(output / "collector.stderr.txt"),
                                 "readiness_timeout_seconds": 30,
                                 "flush_timeout_seconds": plan["flush_timeout_seconds"]}
                write_json(output / "broker-spec.json", specification)
                with (output / "broker.stderr.txt").open("wb") as broker_stderr:
                    broker = subprocess.Popen([sys.executable, str(Path(__file__).with_name("windows.py")), str(output / "broker-spec.json")],
                        stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=broker_stderr, text=True, encoding="utf-8", **hidden_console())
                    broker_events = watch(broker, "broker", ("BROKER_READY", "BROKER_DONE"))
                    started_broker = wait_event(broker, broker_events, "BROKER_READY", guard)
                    result["tokens"].update({"capture": started_broker["capture"], "broker": started_broker["broker"]})
                    send(target, "GO")
                    done = wait_event(target, target_events, "BISTRO_DONE", guard)
                    checked_handshake(done, plan, ready=False)
                    result["events"]["done"] = done
                    send(broker, "STOP")
                    stopped = wait_event(broker, broker_events, "BROKER_DONE", guard)
                    if (stopped.get("returncode") != 0 or stopped.get("sigint_handler_ready_observed") is not True
                            or broker.wait(timeout=10) != 0):
                        raise RuntimeError("Capture failed to stop and flush")
                    broker.stdin.close()
                    broker = None
                    trace = file_identity(output / "capture.tracy")
                    if trace["size_bytes"] < 16:
                        raise ValueError("Capture did not produce a complete nonempty trace")
                    result["trace"] = trace
                    result["events"]["capture_flushed_utc"] = utc()
                    result["events"]["capture_sigint_handler_ready_observed"] = True
                    result["collector_stdout_scope"] = "Rendered snapshots of the owned hidden console; real console stdout exposes Tracy's post-SIGINT-handler progress marker. No unrelated console is read."
                    send(target, "END")
            while target.poll() is None:
                guard()
                time.sleep(0.05)
            if target.wait() != 0:
                raise RuntimeError("Bistro target failed; see retained logs")
            report_path = output / "target/report.json"
            report = load(report_path)
            expected_connected = plan["mode"] == "connected"
            tracing = report.get("tracy", {})
            if (tracing.get("enabled") is not True
                    or tracing.get("connected_at_measurement_start") is not expected_connected
                    or tracing.get("connected_at_measurement_end") is not expected_connected
                    or tracing.get("capture_handshake") is not expected_connected
                    or tracing.get("capture_id") != plan["target_environment"]["RENDERER_TRACY_CAPTURE_ID"]):
                raise ValueError("Target Tracy connection boundaries differ from requested mode")
            result["tracy"] = tracing
            result["connection_observation_scope"] = "Target observed connection state at ROI start/end; disconnected mode launches no collector. No per-frame connection polling, so boundary observations do not prove absence of an unrelated transient collector during the ROI."
            result["runner_metrics"] = validate_report(report, {"api": plan["api"], "gpu_timing": "off"}, plan)
            result["report"] = file_identity(report_path)
            result["identity"] = report["identity"]
            if plan["mode"] == "connected" and result["events"]["done"]["measurement"] != report["measurement"]:
                raise ValueError("DONE measurement changed during post-ROI output")
            if "panicked at" in (output / "target.stderr.txt").read_text(encoding="utf-8", errors="replace"):
                raise ValueError("Target emitted a Rust panic")
            result.update(status="passed", capture_completed=plan["mode"] == "connected")
    except BaseException as error:
        result.update(status="failed", failure=f"{type(error).__name__}: {error}")
        raise
    finally:
        cleanup_errors = []
        def clean(label, operation):
            try:
                operation()
            except Exception as error:
                cleanup_errors.append(f"{label}: {type(error).__name__}: {error}")
        if broker is not None:
            # EOF asks the broker to kill its owned capture before exiting.
            clean("close broker input", broker.stdin.close)
            try:
                broker.wait(timeout=15)
            except (OSError, subprocess.TimeoutExpired) as error:
                clean("terminate broker and its capture job", lambda: stop_owned(broker))
                if broker.poll() is None:
                    cleanup_errors.append(f"broker completion unknown: {error}")
        clean("terminate target", lambda: stop_owned(target))
        if target is not None and target.stdin:
            clean("close target input", target.stdin.close)
        for reader in readers:
            reader.join(timeout=2)
        previously_passed = result["status"] == "passed"
        if cleanup_errors:
            result.update(status="failed", capture_completed=False, cleanup_errors=cleanup_errors)
        result["finished_utc"] = utc()
        result["controller_wall_seconds"] = time.monotonic() - started
        write_json(output / "capture.json", result)
        if cleanup_errors and previously_passed:
            raise RuntimeError("Owned process cleanup failed; see retained capture.json")
    return result


def run_logged(command, output, name, timeout, expected_codes=(0,), *, stage=None,
               max_output_bytes=2 * 1024 * 1024 * 1024):
    stdout, stderr = output / (name + ".stdout.txt"), output / (name + ".stderr.txt")
    with stdout.open("wb") as out, stderr.open("wb") as err:
        process = subprocess.Popen(command, stdout=out, stderr=err, **hidden_console())
        try:
            evidence = require_nonadmin(process.pid, handle=process._handle)
            if stage is not None:
                stage.update(token=evidence, pid=process.pid)
            deadline = time.monotonic() + timeout
            while process.poll() is None:
                if time.monotonic() > deadline:
                    raise subprocess.TimeoutExpired(command, timeout)
                if stdout.stat().st_size + stderr.stat().st_size > max_output_bytes:
                    raise ValueError("Native export/help output exceeded the per-stage polling quota")
                try:
                    process.wait(timeout=0.05)
                except subprocess.TimeoutExpired:
                    pass
            code = process.wait()
            if stdout.stat().st_size + stderr.stat().st_size > max_output_bytes:
                raise ValueError("Native export/help output exceeded the per-stage polling quota")
        finally:
            stop_owned(process)
    if code not in expected_codes:
        raise RuntimeError(f"Tool {name} exited {code}; see logs")
    return {"command": command, "returncode": code, "token": evidence,
            "stdout": file_identity(stdout), "stderr": file_identity(stderr)}


def export_stage(result, command, output, name, timeout, max_output_bytes=2 * 1024 * 1024 * 1024):
    stage = {"command": command, "status": "running", "started_utc": utc(), "max_output_bytes": max_output_bytes}
    result["stages"][name] = stage
    try:
        stage.update(run_logged(command, output, name, timeout, stage=stage,
                                max_output_bytes=max_output_bytes), status="passed")
    except BaseException as error:
        stage.update(status="failed", error=f"{type(error).__name__}: {error}")
        for role in ("stdout", "stderr"):
            path = output / (name + "." + role + ".txt")
            if path.exists():
                stage[role] = file_identity(path)
        raise
    finally:
        stage["finished_utc"] = utc()


def export(args):
    if sys.platform != "win32":
        raise ValueError("Portable Windows export requires Windows")
    if not 0 < args.timeout_seconds <= 3600:
        raise ValueError("Export timeout must be (0,3600]")
    max_output_mib = getattr(args, "max_output_mib", 2048)
    if not 16 <= max_output_mib <= 65536:
        raise ValueError("Export max-output-mib must be [16,65536]")
    record = load(args.capture)
    if record.get("status") != "passed" or record.get("capture_completed") is not True:
        raise ValueError("Export requires a completed valid connected capture")
    plan = record["plan"]
    verify_plan(plan)
    verify_file(record["trace"])
    output = Path(args.output).resolve()
    output.mkdir(parents=True, exist_ok=False)
    result = {"schema_version": 1, "status": "running", "capture": file_identity(args.capture),
              "trace": record["trace"], "plan": plan, "stages": {}, "started_utc": utc(), "export_valid": False,
              "max_output_bytes_per_stage": max_output_mib * 1024 * 1024,
              "quota_scope": "Polling guard for each native export's stdout+stderr; individual writes may transiently exceed it. Temporary disk-backed analysis storage is separate and is removed after analysis.",
              "source_contract": "https://github.com/wolfpld/tracy/blob/v0.14.1/csvexport/src/csvexport.cpp"}
    try:
        result["controller_token"] = require_nonadmin()
        exe = plan["tools"]["csvexport"]["path"]
        export_stage(result, [exe, "--help"], output, "help", args.timeout_seconds, max_output_mib * 1024 * 1024)
        help_text = (output / "help.stdout.txt").read_text(encoding="utf-8", errors="replace") + (output / "help.stderr.txt").read_text(encoding="utf-8", errors="replace")
        if "tracy-csvexport " + TRACY_VERSION not in help_text or "--self" not in help_text or "--unwrap" not in help_text:
            raise ValueError("Actual csvexport help differs from matched pinned tool semantics")
        for name, flags in (("inclusive", []), ("self", ["-e"])):
            export_stage(result, [exe, "-u", "-s", "\t", *flags, record["trace"]["path"]], output, name,
                         args.timeout_seconds, max_output_mib * 1024 * 1024)
        result["analysis"] = analyze_zones(output / "inclusive.stdout.txt", output / "self.stdout.txt", plan["frames"],
                                          plan["target_environment"]["RENDERER_TRACY_CAPTURE_ID"])
        result.update(status="passed", export_valid=True, trace_content_verified=True)
    except BaseException as error:
        result.update(status="failed", failure=f"{type(error).__name__}: {error}")
        raise
    finally:
        result["finished_utc"] = utc()
        write_json(output / "export.json", result)
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    subparsers = parser.add_subparsers(dest="action", required=True)
    for action in ("plan", "capture"):
        command = subparsers.add_parser(action)
        command.add_argument("--build-manifest", type=Path, required=True)
        command.add_argument("--capture-exe", type=Path)
        command.add_argument("--csvexport-exe", type=Path)
        command.add_argument("--tool-provenance", type=Path)
        command.add_argument("--mode", choices=("connected", "disconnected"), default="connected")
        command.add_argument("--api", choices=("vulkan", "d3d12"), required=True)
        assets = command.add_mutually_exclusive_group(required=True)
        assets.add_argument("--manifest", type=Path)
        assets.add_argument("--fixture", action="store_true")
        command.add_argument("--view", default="route")
        for name, default in (("frames", 1800), ("warmup", 3600), ("width", 1920), ("height", 1080), ("inflight", 2)):
            command.add_argument("--" + name, type=int, default=default)
        command.add_argument("--timeout-seconds", type=float, default=300)
        command.add_argument("--flush-timeout-seconds", type=float, default=120)
        command.add_argument("--max-output-mib", type=int, default=2048)
        command.add_argument("--cwd", type=Path, default=ROOT)
        command.add_argument("--output", type=Path, required=True)
    command = subparsers.add_parser("export")
    command.add_argument("--capture", type=Path, required=True)
    command.add_argument("--output", type=Path, required=True)
    command.add_argument("--timeout-seconds", type=float, default=120)
    command.add_argument("--max-output-mib", type=int, default=2048,
                         help="Polling quota per native export, 16..65536 MiB; analysis temporary storage is separate")
    command = subparsers.add_parser("analyze")
    command.add_argument("--export", dest="export_path", type=Path, required=True)
    command.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    try:
        if args.action in ("plan", "capture"):
            plan = make_plan(args)
            result = plan if args.action == "plan" else capture(plan)
        elif args.action == "export":
            result = export(args)
        else:
            record = load(args.export_path)
            if record.get("export_valid") is not True:
                raise ValueError("Analysis requires a successful identified export")
            for stage in ("inclusive", "self"):
                verify_file(record["stages"][stage]["stdout"])
            result = analyze_zones(record["stages"]["inclusive"]["stdout"]["path"], record["stages"]["self"]["stdout"]["path"], record["plan"]["frames"],
                                   record["plan"]["target_environment"]["RENDERER_TRACY_CAPTURE_ID"])
            if args.output.exists():
                raise ValueError("Analysis output must be new")
            write_json(args.output, result)
        print(json.dumps(result if args.action == "plan" else {"status": result.get("status", "passed"), "action": args.action}, indent=2))
    except (ValueError, OSError, KeyError, RuntimeError, subprocess.TimeoutExpired) as error:
        print(f"Tracy {args.action} failed: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

.tools/cpu-opt-evidence/compare_builds.p.source:
"""Serial matched archived Bistro before/after runs; no machine settings changes."""
import argparse
import hashlib
from datetime import datetime, timezone
import json
from pathlib import Path
import subprocess
import sys
import time

ROOT = Path(__file__).resolve().parents[2]
sys.path[:0] = [str(ROOT / 'tools/bistro'), str(ROOT / 'tools/cpu_profile'), str(ROOT / 'tools/tracy')]
from measure_runtime import verified_release, validate_report, aggregate, query_cost_observations
from compare_runtime import digest, compare_reports
from windows import require_nonadmin, own_process_job

def utc():
    return datetime.now(timezone.utc).isoformat()

def write(path, value):
    path.write_text(json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False) + '\n', encoding='utf8')

def identity(path):
    path = Path(path).resolve()
    return dict(path=str(path), sha256=digest(path), bytes=path.stat().st_size)

def matched(before, after):
    fields = ('profile', 'effective_features', 'instrumentation', 'artifact_class', 'example',
              'rustc', 'cargo', 'host', 'cargo_profile', 'profile_settings', 'incremental')
    for field in fields:
        if before['build'][field] != after['build'][field]:
            raise ValueError('Different build configuration: ' + field)
    if [c['sha256'] for c in before['build']['cargo_configuration']] != [c['sha256'] for c in after['build']['cargo_configuration']]:
        raise ValueError('Different Cargo configuration bytes')

def schedule(modes):
    conditions = [(api, mode) for mode in modes for api in ('vulkan', 'd3d12')]
    runs = []
    for repetition in range(1, 4):
        offset = (repetition - 1) % len(conditions)
        rotated = conditions[offset:] + conditions[:offset]
        for api, mode in rotated:
            for variant in (('before', 'after') if repetition % 2 else ('after', 'before')):
                runs.append(dict(api=api, gpu_timing=mode, repetition=repetition, variant=variant,
                                 run_id=f'{variant}-{api}-gpu-{mode}-{repetition}'))
    return runs

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--before', type=Path, required=True)
    parser.add_argument('--after', type=Path, required=True)
    parser.add_argument('--manifest', type=Path, required=True)
    parser.add_argument('--gpu-modes', nargs='+', choices=('off', 'on'), default=['off', 'on'])
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--plan-only', action='store_true')
    args = parser.parse_args()
    if not args.gpu_modes or len(set(args.gpu_modes)) != len(args.gpu_modes):
        raise ValueError('Choose distinct GPU modes')
    own_job = own_process_job()
    token = require_nonadmin()
    builds = {}
    for name in ('before', 'after'):
        path = getattr(args, name).resolve()
        manifest, binary = verified_release(path)
        builds[name] = dict(manifest=identity(path), binary_path=str(binary), metadata=manifest)
    matched(builds['before']['metadata'], builds['after']['metadata'])
    output = args.output.resolve()
    if output.exists():
        raise ValueError('Output must be a new directory')
    settings = dict(frames=1800, warmup=3600, width=1920, height=1080, inflight=2, view='route')
    inputs = [identity(args.manifest), identity(ROOT / 'tools/bistro/conditions.json')]
    helpers = [identity(Path(__file__)), *[identity(ROOT / p) for p in
        ('tools/bistro/measure_runtime.py', 'tools/bistro/compare_runtime.py', 'tools/cpu_profile/identity.py', 'tools/tracy/windows.py')]]
    plan = dict(schema_version=1, created_utc=utc(), builds=builds, settings=settings, inputs=inputs,
                helpers=helpers, schedule=schedule(args.gpu_modes), controller_token=token,
                scope='Adjacent before/after independent processes; order alternates by repetition. Native timers plus GPU queries off/on are separate conditions. Full ROI includes final drain; post-ROI frame0 image check. No affinity/power changes, build or analysis concurrent with target ROI. Observed independent-run differences, not universal speedup.')
    if args.plan_only:
        print(json.dumps(plan, indent=2))
        return
    output.mkdir(exist_ok=False)
    write(output / 'plan.json', plan)
    result = dict(schema_version=1, status='running', started_utc=utc(), runs=[])
    def save():
        write(output / 'summary.json', result)
    save()
    common_identity = None
    devices = {}
    try:
        for condition in plan['schedule']:
            build = builds[condition['variant']]
            for item in (*inputs, *helpers, build['manifest']):
                if digest(item['path']) != item['sha256']:
                    raise ValueError('Input/helper changed: ' + item['path'])
            if digest(build['binary_path']) != build['metadata']['binary']['sha256']:
                raise ValueError('Archived executable changed')
            destination = output / condition['run_id']
            command = [build['binary_path'], '--api', condition['api'], '--manifest', str(args.manifest.resolve()), '--output', str(destination)]
            for key, value in settings.items():
                command += ['--' + key, str(value)]
            if condition['gpu_timing'] == 'on':
                command.append('--gpu-timing')
            record = dict(**condition, status='running', command=command, started_utc=utc())
            result['runs'].append(record)
            save()
            print(utc(), 'START', condition['run_id'], flush=True)
            started = time.perf_counter()
            with (output / (condition['run_id'] + '.stdout.txt')).open('wb') as stdout, (output / (condition['run_id'] + '.stderr.txt')).open('wb') as stderr:
                process = subprocess.Popen(command, cwd=ROOT, stdout=stdout, stderr=stderr, creationflags=subprocess.CREATE_NO_WINDOW)
                try:
                    record['token'] = require_nonadmin(process.pid, handle=process._handle)
                    record['returncode'] = process.wait(timeout=600)
                finally:
                    if process.poll() is None:
                        process.kill()
                        process.wait()
            record['controller_wall_seconds'] = time.perf_counter() - started
            if record['returncode']:
                raise RuntimeError('Target failed: ' + condition['run_id'])
            report_path = destination / 'report.json'
            report_payload = report_path.read_bytes()
            report = json.loads(report_payload)
            if report.get('tracy') is not None:
                raise ValueError('Normal build unexpectedly contains Tracy reporting')
            device = {k:v for k,v in report['runtime'].items() if k not in ('process_id', 'main_thread_id')}
            if devices.setdefault(condition['api'], device) != device:
                raise ValueError('Device/driver changed within an API')
            if common_identity is None:
                common_identity = report['identity']
            if (report['identity'] != common_identity
                    or report['identity']['cook_manifest_sha256'] != inputs[0]['sha256']
                    or report['identity']['conditions_sha256'] != inputs[1]['sha256']):
                raise ValueError('Rendering identity changed across builds/conditions')
            record.update(report=dict(path=str(report_path), sha256=hashlib.sha256(report_payload).hexdigest(), bytes=len(report_payload)), identity=report['identity'], runtime=report['runtime'],
                metrics=validate_report(report, condition, settings), status='passed', finished_utc=utc())
            native = report['measurement']['native_phase_totals_ns']
            native_enabled = condition['gpu_timing'] == 'on'
            if report['measurement']['native_profiling_enabled'] is not native_enabled:
                raise ValueError('Native timing mode mismatch')
            if native_enabled:
                if not isinstance(native, dict) or set(native) != {'prepare', 'record', 'retire', 'submit'}:
                    raise ValueError('Incomplete native timing phases')
                for key, total in native.items():
                    if type(total) is not int or total < 0:
                        raise ValueError('Invalid native time')
                    record['metrics']['native_' + key + '_ns_per_frame'] = total / settings['frames']
            elif native is not None:
                raise ValueError('Disabled native timing must remain missing')
            save()
            print(utc(), 'DONE', condition['run_id'], 'cpu_ms', round(record['metrics']['process_cpu_ns_per_frame']/1e6,3), 'wall_ms', round(record['metrics']['wall_ns_per_frame']/1e6,3), flush=True)
        # All GPU ROIs ended before offline image analysis.
        references = {}
        for run in result['runs']:
            report_path = Path(run['report']['path'])
            if identity(report_path) != run['report']:
                raise ValueError('Report changed after measurement: ' + run['run_id'])
            comparison = compare_reports(references.setdefault(run['api'], report_path), report_path, profile='repeat')
            run['post_roi_capture'] = comparison
            if not comparison['passed']:
                raise ValueError('Image changed: ' + run['run_id'])
        result['cross_api_image'] = compare_reports(references['vulkan'], references['d3d12'], profile='scene')
        if not result['cross_api_image']['passed']:
            raise ValueError('Cross-API image failed')
        result['aggregates'] = {v: aggregate([r for r in result['runs'] if r['variant'] == v]) for v in builds}
        result['query_observations'] = {v: query_cost_observations(a) for v, a in result['aggregates'].items()}
        observations = {}
        for key, before in result['aggregates']['before'].items():
            after = result['aggregates']['after'][key]
            observations[key] = {metric: dict(before=b['median_of_runs'], after=after['metrics'][metric]['median_of_runs'],
                percent_change=(after['metrics'][metric]['median_of_runs']/b['median_of_runs']-1)*100 if b['median_of_runs'] else None)
                for metric, b in before['metrics'].items()}
        result.update(status='passed', observed_changes=observations)
    except BaseException as error:
        result.update(status='failed', failure=f'{type(error).__name__}: {error}')
        raise
    finally:
        result['finished_utc'] = utc()
        save()

if __name__ == '__main__':
    main()

.tools/cpu-opt-evidence/compare_builds_h.source:
"""Serial matched archived Bistro before/after runs; no machine settings changes."""
import argparse
import hashlib
from datetime import datetime, timezone
import json
from pathlib import Path
import subprocess
import sys
import time

ROOT = Path(__file__).resolve().parents[2]
sys.path[:0] = [str(ROOT / 'tools/bistro'), str(ROOT / 'tools/cpu_profile'), str(ROOT / 'tools/tracy')]
from measure_runtime import verified_release, validate_report, aggregate, query_cost_observations
from compare_runtime import digest, compare_reports
from windows import require_nonadmin as base_require_nonadmin, own_process_job
from host_token import require_host_nonadmin

def require_nonadmin(pid=None, *, handle=None):
    return require_host_nonadmin(base_require_nonadmin, pid, handle=handle)

def utc():
    return datetime.now(timezone.utc).isoformat()

def write(path, value):
    path.write_text(json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False) + '\n', encoding='utf8')

def identity(path):
    path = Path(path).resolve()
    return dict(path=str(path), sha256=digest(path), bytes=path.stat().st_size)

def matched(before, after):
    fields = ('profile', 'effective_features', 'instrumentation', 'artifact_class', 'example',
              'rustc', 'cargo', 'host', 'cargo_profile', 'profile_settings', 'incremental')
    for field in fields:
        if before['build'][field] != after['build'][field]:
            raise ValueError('Different build configuration: ' + field)
    if [c['sha256'] for c in before['build']['cargo_configuration']] != [c['sha256'] for c in after['build']['cargo_configuration']]:
        raise ValueError('Different Cargo configuration bytes')

def schedule(modes):
    conditions = [(api, mode) for mode in modes for api in ('vulkan', 'd3d12')]
    runs = []
    for repetition in range(1, 4):
        offset = (repetition - 1) % len(conditions)
        rotated = conditions[offset:] + conditions[:offset]
        for api, mode in rotated:
            for variant in (('before', 'after') if repetition % 2 else ('after', 'before')):
                runs.append(dict(api=api, gpu_timing=mode, repetition=repetition, variant=variant,
                                 run_id=f'{variant}-{api}-gpu-{mode}-{repetition}'))
    return runs

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--before', type=Path, required=True)
    parser.add_argument('--after', type=Path, required=True)
    parser.add_argument('--manifest', type=Path, required=True)
    parser.add_argument('--gpu-modes', nargs='+', choices=('off', 'on'), default=['off', 'on'])
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--plan-only', action='store_true')
    args = parser.parse_args()
    if not args.gpu_modes or len(set(args.gpu_modes)) != len(args.gpu_modes):
        raise ValueError('Choose distinct GPU modes')
    own_job = own_process_job()
    token = require_nonadmin()
    builds = {}
    for name in ('before', 'after'):
        path = getattr(args, name).resolve()
        manifest, binary = verified_release(path)
        builds[name] = dict(manifest=identity(path), binary_path=str(binary), metadata=manifest)
    matched(builds['before']['metadata'], builds['after']['metadata'])
    output = args.output.resolve()
    if output.exists():
        raise ValueError('Output must be a new directory')
    settings = dict(frames=1800, warmup=3600, width=1920, height=1080, inflight=2, view='route')
    inputs = [identity(args.manifest), identity(ROOT / 'tools/bistro/conditions.json')]
    helpers = [identity(Path(__file__)), identity(Path(__file__).with_name('host_token.py')), *[identity(ROOT / p) for p in
        ('tools/bistro/measure_runtime.py', 'tools/bistro/compare_runtime.py', 'tools/cpu_profile/identity.py', 'tools/tracy/windows.py')]]
    plan = dict(schema_version=1, created_utc=utc(), builds=builds, settings=settings, inputs=inputs,
                helpers=helpers, schedule=schedule(args.gpu_modes), controller_token=token,
                scope='Adjacent before/after independent processes; order alternates by repetition. Native timers plus GPU queries off/on are separate conditions. Full ROI includes final drain; post-ROI frame0 image check. No affinity/power changes, build or analysis concurrent with target ROI. Observed independent-run differences, not universal speedup.')
    if args.plan_only:
        print(json.dumps(plan, indent=2))
        return
    output.mkdir(exist_ok=False)
    write(output / 'plan.json', plan)
    result = dict(schema_version=1, status='running', started_utc=utc(), runs=[])
    def save():
        write(output / 'summary.json', result)
    save()
    common_identity = None
    devices = {}
    try:
        for condition in plan['schedule']:
            build = builds[condition['variant']]
            for item in (*inputs, *helpers, build['manifest']):
                if digest(item['path']) != item['sha256']:
                    raise ValueError('Input/helper changed: ' + item['path'])
            if digest(build['binary_path']) != build['metadata']['binary']['sha256']:
                raise ValueError('Archived executable changed')
            destination = output / condition['run_id']
            command = [build['binary_path'], '--api', condition['api'], '--manifest', str(args.manifest.resolve()), '--output', str(destination)]
            for key, value in settings.items():
                command += ['--' + key, str(value)]
            if condition['gpu_timing'] == 'on':
                command.append('--gpu-timing')
            record = dict(**condition, status='running', command=command, started_utc=utc())
            result['runs'].append(record)
            save()
            print(utc(), 'START', condition['run_id'], flush=True)
            started = time.perf_counter()
            with (output / (condition['run_id'] + '.stdout.txt')).open('wb') as stdout, (output / (condition['run_id'] + '.stderr.txt')).open('wb') as stderr:
                process = subprocess.Popen(command, cwd=ROOT, stdout=stdout, stderr=stderr, creationflags=subprocess.CREATE_NO_WINDOW)
                try:
                    record['token'] = require_nonadmin(process.pid, handle=process._handle)
                    record['returncode'] = process.wait(timeout=600)
                finally:
                    if process.poll() is None:
                        process.kill()
                        process.wait()
            record['controller_wall_seconds'] = time.perf_counter() - started
            if record['returncode']:
                raise RuntimeError('Target failed: ' + condition['run_id'])
            report_path = destination / 'report.json'
            report_payload = report_path.read_bytes()
            report = json.loads(report_payload)
            if report.get('tracy') is not None:
                raise ValueError('Normal build unexpectedly contains Tracy reporting')
            device = {k:v for k,v in report['runtime'].items() if k not in ('process_id', 'main_thread_id')}
            if devices.setdefault(condition['api'], device) != device:
                raise ValueError('Device/driver changed within an API')
            if common_identity is None:
                common_identity = report['identity']
            if (report['identity'] != common_identity
                    or report['identity']['cook_manifest_sha256'] != inputs[0]['sha256']
                    or report['identity']['conditions_sha256'] != inputs[1]['sha256']):
                raise ValueError('Rendering identity changed across builds/conditions')
            record.update(report=dict(path=str(report_path), sha256=hashlib.sha256(report_payload).hexdigest(), bytes=len(report_payload)), identity=report['identity'], runtime=report['runtime'],
                metrics=validate_report(report, condition, settings), status='passed', finished_utc=utc())
            native = report['measurement']['native_phase_totals_ns']
            native_enabled = condition['gpu_timing'] == 'on'
            if report['measurement']['native_profiling_enabled'] is not native_enabled:
                raise ValueError('Native timing mode mismatch')
            if native_enabled:
                if not isinstance(native, dict) or set(native) != {'prepare', 'record', 'retire', 'submit'}:
                    raise ValueError('Incomplete native timing phases')
                for key, total in native.items():
                    if type(total) is not int or total < 0:
                        raise ValueError('Invalid native time')
                    record['metrics']['native_' + key + '_ns_per_frame'] = total / settings['frames']
            elif native is not None:
                raise ValueError('Disabled native timing must remain missing')
            save()
            print(utc(), 'DONE', condition['run_id'], 'cpu_ms', round(record['metrics']['process_cpu_ns_per_frame']/1e6,3), 'wall_ms', round(record['metrics']['wall_ns_per_frame']/1e6,3), flush=True)
        # All GPU ROIs ended before offline image analysis.
        references = {}
        for run in result['runs']:
            report_path = Path(run['report']['path'])
            if identity(report_path) != run['report']:
                raise ValueError('Report changed after measurement: ' + run['run_id'])
            comparison = compare_reports(references.setdefault(run['api'], report_path), report_path, profile='repeat')
            run['post_roi_capture'] = comparison
            if not comparison['passed']:
                raise ValueError('Image changed: ' + run['run_id'])
        result['cross_api_image'] = compare_reports(references['vulkan'], references['d3d12'], profile='scene')
        if not result['cross_api_image']['passed']:
            raise ValueError('Cross-API image failed')
        result['aggregates'] = {v: aggregate([r for r in result['runs'] if r['variant'] == v]) for v in builds}
        result['query_observations'] = {v: query_cost_observations(a) for v, a in result['aggregates'].items()}
        observations = {}
        for key, before in result['aggregates']['before'].items():
            after = result['aggregates']['after'][key]
            observations[key] = {metric: dict(before=b['median_of_runs'], after=after['metrics'][metric]['median_of_runs'],
                percent_change=(after['metrics'][metric]['median_of_runs']/b['median_of_runs']-1)*100 if b['median_of_runs'] else None)
                for metric, b in before['metrics'].items()}
        result.update(status='passed', observed_changes=observations)
    except BaseException as error:
        result.update(status='failed', failure=f'{type(error).__name__}: {error}')
        raise
    finally:
        result['finished_utc'] = utc()
        save()

if __name__ == '__main__':
    main()

.tools/cpu-opt-evidence/resume_host_matr.source:
"""Retain 22 valid host runs and repeat the rejected final pair unchanged."""
import json
from pathlib import Path
import subprocess
import time
import compare_builds_host as base

ROOT = base.ROOT
EVIDENCE = ROOT / '.tools/cpu-opt-evidence'

def main():
    owned_job = base.own_process_job()
    token = base.require_nonadmin()
    parent = EVIDENCE / 'performance-host'
    old_plan = json.loads((parent / 'plan.json').read_text())
    old_result = json.loads((parent / 'summary.json').read_text())
    if old_result['status'] != 'failed' or old_result['failure'] != 'MeasurementError: QPC and wall measurement windows disagree':
        raise ValueError('Only the identified timing-window rejection may be resumed')
    if len(old_result['runs']) != 23 or any(r['status'] != 'passed' for r in old_result['runs'][:22]):
        raise ValueError('Require exactly 22 valid prefix runs and the rejected 23rd attempt')
    if old_result['runs'][-1]['run_id'] != 'before-d3d12-gpu-off-3':
        raise ValueError('Unexpected rejected condition')
    output = EVIDENCE / 'performance-host-completed'
    output.mkdir(exist_ok=False)
    settings = old_plan['settings']
    builds = old_plan['builds']
    for build in builds.values():
        metadata, binary = base.verified_release(Path(build['manifest']['path']))
        if metadata != build['metadata'] or str(binary) != build['binary_path']:
            raise ValueError('Archived build identity changed')
    for item in old_plan['inputs'] + old_plan['helpers'] + [b['manifest'] for b in builds.values()]:
        if base.digest(item['path']) != item['sha256']:
            raise ValueError('Frozen input/helper changed')
    accepted = old_result['runs'][:22]
    common_identity = accepted[0]['identity']
    devices = {}
    for run, condition in zip(accepted, old_plan['schedule'][:22]):
        if any(run[k] != condition[k] for k in condition):
            raise ValueError('Valid prefix differs from frozen schedule')
        if base.identity(run['report']['path']) != run['report']:
            raise ValueError('Prior accepted report changed')
        report = json.loads(Path(run['report']['path']).read_text())
        checked = base.validate_report(report, run, settings)
        if any(run['metrics'][k] != value for k, value in checked.items()):
            raise ValueError('Prior accepted metric does not reproduce')
        device = {k:v for k,v in report['runtime'].items() if k not in ('process_id','main_thread_id')}
        if devices.setdefault(run['api'], device) != device or report['identity'] != common_identity:
            raise ValueError('Prior identity/device changed')
    bad = old_result['runs'][-1]
    bad_path = Path(bad['command'][bad['command'].index('--output') + 1]) / 'report.json'
    bad_report = json.loads(bad_path.read_text())
    plan = dict(old_plan, controller_token=token, created_utc=base.utc(),
        parent_plan=base.identity(parent / 'plan.json'), parent_summary=base.identity(parent / 'summary.json'),
        resume_scope='Keep 22 original valid processes; reject only the predefined QPC/wall window inconsistency, retain original bytes, rerun the final before/after pair with unchanged archived binaries/inputs/settings. No timing threshold change or performance-outlier selection.',
        helpers=old_plan['helpers'] + [base.identity(__file__)],
        rejected_attempt=dict(record=bad, report=base.identity(bad_path), measurement=bad_report['measurement'], reason=old_result['failure']))
    base.write(output / 'plan.json', plan)
    result = dict(schema_version=1, status='running', started_utc=base.utc(), runs=accepted,
                  resumed_from=plan['parent_summary'], rejected_attempt=plan['rejected_attempt'])
    def save():
        base.write(output / 'summary.json', result)
    save()
    try:
        for condition in old_plan['schedule'][22:]:
            build = builds[condition['variant']]
            for item in plan['inputs'] + plan['helpers'] + [build['manifest']]:
                if base.digest(item['path']) != item['sha256']:
                    raise ValueError('Frozen input/helper changed')
            if base.digest(build['binary_path']) != build['metadata']['binary']['sha256']:
                raise ValueError('Archived executable changed')
            destination = output / (condition['run_id'] + '-attempt-2')
            command = [build['binary_path'], '--api', condition['api'], '--manifest', plan['inputs'][0]['path'], '--output', str(destination)]
            for key, value in settings.items():
                command += ['--' + key, str(value)]
            if condition['gpu_timing'] == 'on':
                command.append('--gpu-timing')
            record = dict(**condition, attempt=2, status='running', command=command, started_utc=base.utc())
            result['runs'].append(record)
            save()
            print(base.utc(), 'START', condition['run_id'], 'attempt2', flush=True)
            started = time.perf_counter()
            with (output / (condition['run_id'] + '.stdout.txt')).open('wb') as stdout, (output / (condition['run_id'] + '.stderr.txt')).open('wb') as stderr:
                process = subprocess.Popen(command, cwd=ROOT, stdout=stdout, stderr=stderr, creationflags=subprocess.CREATE_NO_WINDOW)
                try:
                    record['token'] = base.require_nonadmin(process.pid, handle=process._handle)
                    record['returncode'] = process.wait(timeout=600)
                finally:
                    if process.poll() is None:
                        process.kill()
                        process.wait()
            record['controller_wall_seconds'] = time.perf_counter() - started
            if record['returncode']:
                raise ValueError('Resumed target failed')
            report_path = destination / 'report.json'
            report = json.loads(report_path.read_text())
            if report.get('tracy') is not None or report['identity'] != common_identity:
                raise ValueError('Rendering/instrumentation identity changed')
            device = {k:v for k,v in report['runtime'].items() if k not in ('process_id','main_thread_id')}
            if devices[condition['api']] != device:
                raise ValueError('Device/driver changed')
            metrics = base.validate_report(report, condition, settings)
            if condition['gpu_timing'] != 'off' or report['measurement']['native_profiling_enabled'] is not False or report['measurement']['native_phase_totals_ns'] is not None:
                raise ValueError('Only the original disabled native/query final pair is expected')
            record.update(report=base.identity(report_path), identity=report['identity'], runtime=report['runtime'], metrics=metrics, status='passed', finished_utc=base.utc())
            # Keep the original absolute-path report record schema.
            record['report']['path'] = str(report_path)
            save()
            print(base.utc(), 'DONE', condition['run_id'], 'cpu_ms', round(metrics['process_cpu_ns_per_frame']/1e6,3), 'wall_ms', round(metrics['wall_ns_per_frame']/1e6,3), flush=True)
        references = {}
        for run in result['runs']:
            path = Path(run['report']['path'])
            if base.identity(path) != run['report']:
                raise ValueError('Report changed before image comparison')
            comparison = base.compare_reports(references.setdefault(run['api'], path), path, profile='repeat')
            run['post_roi_capture'] = comparison
            if not comparison['passed']:
                raise ValueError('Post-ROI rendering changed')
        result['cross_api_image'] = base.compare_reports(references['vulkan'], references['d3d12'], profile='scene')
        if not result['cross_api_image']['passed']:
            raise ValueError('Cross-API image comparison failed')
        result['aggregates'] = {v:base.aggregate([r for r in result['runs'] if r['variant']==v]) for v in builds}
        result['query_observations'] = {v:base.query_cost_observations(a) for v,a in result['aggregates'].items()}
        result['observed_changes'] = {key:{metric:dict(before=b['median_of_runs'], after=result['aggregates']['after'][key]['metrics'][metric]['median_of_runs'],
            percent_change=(result['aggregates']['after'][key]['metrics'][metric]['median_of_runs']/b['median_of_runs']-1)*100 if b['median_of_runs'] else None)
            for metric,b in before['metrics'].items()} for key,before in result['aggregates']['before'].items()}
        result['status'] = 'passed'
    except BaseException as error:
        result.update(status='failed', failure=f'{type(error).__name__}: {error}')
        raise
    finally:
        result['finished_utc'] = base.utc()
        save()
    print('PASSED resumed 24-process host cohort', flush=True)

if __name__ == '__main__':
    main()

.tools/cpu-opt-evidence/verify_host_repo.source:
"""Bind every accepted host metric to one immutable report-byte snapshot."""
from collections import Counter
import hashlib
import json
from pathlib import Path
import compare_builds_host as base

ROOT = base.ROOT
EVIDENCE = ROOT / '.tools/cpu-opt-evidence'

def file_snapshot(path):
    path = Path(path).resolve()
    payload = path.read_bytes()
    return payload, dict(path=str(path), sha256=hashlib.sha256(payload).hexdigest(), bytes=len(payload))

def main():
    path = EVIDENCE / 'performance-host-completed/summary.json'
    summary_payload, summary_identity = file_snapshot(path)
    summary = json.loads(summary_payload)
    plan_path = path.with_name('plan.json')
    plan_payload, plan_identity = file_snapshot(plan_path)
    plan = json.loads(plan_payload)
    if summary['status'] != 'passed' or len(summary['runs']) != 24:
        raise ValueError('Require the full accepted host cohort')
    expected = Counter({(api,mode,variant):3 for api in ('vulkan','d3d12') for mode in ('off','on') for variant in ('before','after')})
    if Counter((r['api'],r['gpu_timing'],r['variant']) for r in summary['runs']) != expected:
        raise ValueError('Wrong independent-process cohort counts')
    proof_path = EVIDENCE / 'host-report-snapshot-proof.json'
    if proof_path.exists():
        raise ValueError('Never overwrite a report snapshot proof')
    proof = dict(status='running', summary=summary_identity, plan=plan_identity, checked=[],
        method='For each accepted run, read report bytes once; derive SHA/length, parse and reproduce every metric, identity and runtime from that exact payload; compare to recorded row. Original summary and plan must remain byte-identical throughout. No timing threshold changes.',
        helper=base.identity(__file__))
    try:
        for run in summary['runs']:
            payload, actual = file_snapshot(run['report']['path'])
            if actual != run['report']:
                raise ValueError('Report byte identity changed: ' + run['run_id'])
            report = json.loads(payload)
            if report['identity'] != run['identity'] or report['runtime'] != run['runtime']:
                raise ValueError('Stored identity/runtime differs from exact report bytes')
            metrics = base.validate_report(report, run, plan['settings'])
            enabled = run['gpu_timing'] == 'on'
            measurement = report['measurement']
            if measurement['native_profiling_enabled'] is not enabled:
                raise ValueError('Native timing mode mismatch')
            native = measurement['native_phase_totals_ns']
            if enabled:
                if not isinstance(native,dict) or set(native) != {'prepare','record','retire','submit'}:
                    raise ValueError('Native phase keys mismatch')
                for key,total in native.items():
                    if type(total) is not int or total < 0:
                        raise ValueError('Invalid native phase duration')
                    metrics['native_' + key + '_ns_per_frame'] = total / plan['settings']['frames']
            elif native is not None:
                raise ValueError('Disabled native timing must be absent')
            if metrics != run['metrics']:
                raise ValueError('Stored metrics differ from exact report bytes: ' + run['run_id'])
            if run['token']['token_elevation'] != 0 or run['token']['token_is_app_container'] != 0:
                raise ValueError('Accepted target token differs from ordinary-host scope')
            proof['checked'].append(dict(run_id=run['run_id'], report=actual, metrics=metrics, token=run['token'], passed=True))
        if file_snapshot(path)[1] != summary_identity or file_snapshot(plan_path)[1] != plan_identity:
            raise ValueError('Source cohort metadata changed during snapshot verification')
        proof['status'] = 'passed'
    except BaseException as error:
        proof.update(status='failed', failure=f'{type(error).__name__}: {error}')
        raise
    finally:
        proof_path.write_text(json.dumps(proof,indent=2,allow_nan=False)+'\n',encoding='utf8')
